using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer;

// Tool classes are discovered by the MCP SDK via [McpServerToolType].
// The SDK instantiates this class per invocation, injecting constructor
// dependencies from the DI container automatically.
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // The SDK resolves constructor parameters from DI.
    // Because we register a named HttpClient ("weather"), we inject
    // IHttpClientFactory and create the client manually.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _http = httpClientFactory.CreateClient("weather");
    }

    [McpServerTool(Name = "get_forecast"),
     Description("Get the weather forecast for a city. Returns temperature, conditions, and humidity.")]
    public async Task<WeatherResponse> GetForecastAsync(
        [Description("City name, e.g. 'Seattle' or 'London'")] string city,
        [Description("Temperature unit: 'celsius' or 'fahrenheit' (default: celsius)")]
        string units = "celsius")
    {
        var response = await _http.GetFromJsonAsync<WeatherResponse>(
            $"/weather?city={Uri.EscapeDataString(city)}&units={Uri.EscapeDataString(units)}");

        return response ?? throw new InvalidOperationException($"No forecast data for '{city}'");
    }

    [McpServerTool(Name = "get_alerts"),
     Description("Get active weather alerts for a US state by two-letter code.")]
    public async Task<List<AlertResponse>> GetAlertsAsync(
        [Description("Two-letter US state code, e.g. 'WA', 'CA'")] string state)
    {
        var alerts = await _http.GetFromJsonAsync<List<AlertResponse>>(
            $"/alerts?state={Uri.EscapeDataString(state)}");

        return alerts ?? [];
    }
}

public record WeatherResponse(
    [property: JsonPropertyName("city")] string City,
    [property: JsonPropertyName("temperature")] double Temperature,
    [property: JsonPropertyName("units")] string Units,
    [property: JsonPropertyName("conditions")] string Conditions,
    [property: JsonPropertyName("humidity")] int Humidity);

public record AlertResponse(
    [property: JsonPropertyName("title")] string Title,
    [property: JsonPropertyName("severity")] string Severity,
    [property: JsonPropertyName("description")] string Description);

